fn fibonacci(n: u64) -> u64 {
    if n <= 1 {
        return n;
    }
    let mut prev = 1;
    let mut next = 1;
    for _ in 2..n {
        let sum = prev + next;
        prev = next;
        next = sum;
    }
    next
}

