fn parse_int(s: Str) -> Option<Int> {
    if s.len() == 0 {
        return None
    }
    let mut i = 0
    let mut is_neg = false
    if s.get(0) == "-" {
        is_neg = true
        i = 1
    }
    let mut acc = 0
    while i < s.len() {
        let digit = s.get(i) - 48
        if digit < 0 || digit > 9 {
            return None
        }
        acc = 10 * acc + digit
        i = i + 1
    }
    if is_neg {
        Some(-acc)
    } else {
        Some(acc)
    }
}

