    let word_sequence_as_chars = chars(word_sequence)
    let vowels = vec()
    for i in range(0, word_sequence_as_chars) {
        let current_char = get(word_sequence_as_chars, i)
        if (current_char == "a") {
            push(vowels, current_char)
        }
        if (current_char == "e") {
            push(vowels, current_char)
        }
        if (current_char == "i") {
            push(vowels, current_char)
        }
        if (current_char == "o") {
            push(vowels, current_char)
        }
        if (current_char == "u") {
            push(vowels, current_char)
        }
    }
    let number_of_vowels = len(vowels)
    print(number_of_vowels)
}

fn main() {
    let vowels = vec_from_string("aeiouAEIOU".to_string(), 5)
    let word_sequence = vec_from_string("aeiou".to_string(), 8)
    let mut vowel_count = 0
    for letter in &word_sequence {
        if contains_vowel(&vowels, letter) {
            vowel_count = vowel_count + 1
        }
    }
    print(vowel_count)
}

fn contains_vowel(vowels: &Vec<Char>, letter: &Char) -> Bool {
    for vowel in vowels {
        if vowel == letter {
            return true
        }
    }
    false
}

fn vec_from_string(s: Str, count: Int) -> Vec<Char> {
    let mut v = vec()
    for c in &s {
        for _ in 0.to_int() < count {
            v = push(v, c)
        }
    }
    v
}

