fn div(num: Int, denom: Int) -> Option<Int> {
    if denom == 0 {
        None
    } else {
        Some(num / denom)
    }
}

fn main() {
    match div(20, 4) {
        Some(answer) => print(answer),
        None => print_str("bad"),
    }
}

fn div(n: Int, d: Int) -> Option<Int> {
    if d == 0 {
        None
    } else {
        Some(n / d)
    }
}

fn main() {
    match div(20, 4) {
        Some(n) => print(n),
        None => print_str("bad"),
    }
}

fn divide(dividend: u32, divisor: u32) -> Result<u32, &'static str> {
    if divisor == 0 {
        return Err("Cannot divide by zero");
    }
    Ok(dividend / divisor)
}

fn main() {
    match divide(20, 4) {
        Ok(answer) => println!("{}", answer),
        Err(err) => println!("{}", err),
    }
}

